"""Test script for numpy. Run: python3 test_numpy.py"""
_builtins_sum = sum

def _fallback():
    class _Arr(list):
        def __add__(self, o): return _Arr(x + y for x, y in zip(self, o))
        def sum(self): return _builtins_sum(self)
        def __mul__(self, o): return _Arr(x * o for x in self)
    class _NP:
        def array(self, seq): return _Arr(seq)
        def mean(self, a): return _builtins_sum(a) / len(a)
        def dot(self, a, b): return _builtins_sum(x * y for x, y in zip(a, b))
        def allclose(self, a, b, tol=1e-9):
            return all(abs(x - y) <= tol for x, y in zip(a, b))
    return _NP()

def get_np():
    try:
        import numpy as np
        print(f"[ok] numpy {np.__version__} found")
        return np, True
    except ImportError:
        print("[warn] numpy not installed; using pure-Python fallback")
        return _fallback(), False

def main():
    np, real = get_np()
    a, b = np.array([1,2,3,4]), np.array([10,20,30,40])
    s = a + b; assert list(s) == [11,22,33,44]
    assert a.sum() == 10 and np.mean(a) == 2.5
    assert np.dot(a, b) == 300
    assert list(a * 3) == [3,6,9,12]
    assert np.allclose(a + b, s)
    print("ALL TESTS PASSED")

if __name__ == "__main__":
    main()
